import React from "react";
import "./ExperienceCard.css";

function ExperienceCard(props) {
  const experience = props.experience;
  const theme = props.theme;

  // Get color based on experience type
  const getColor = () => {
    return experience.color || "#2962FF";
  };

  // Format duration for better display
  const formatDuration = (duration) => {
    if (!duration) return "";
    return duration;
  };

  // Format location for better display
  const formatLocation = (location) => {
    if (!location || location.trim() === "") return "Remote";
    return location;
  };

  const isCurrent = /present/i.test(experience["duration"] || "");

  // Feeds the CSS spotlight (--mouse-x/y) and a slight tilt toward the
  // pointer (--tilt-x/y). Written straight to the element, no re-render.
  const onPointerMove = (e) => {
    if (e.pointerType !== "mouse") return;
    const el = e.currentTarget;
    const r = el.getBoundingClientRect();
    const x = (e.clientX - r.left) / r.width;
    const y = (e.clientY - r.top) / r.height;
    el.style.setProperty("--mouse-x", `${x * 100}%`);
    el.style.setProperty("--mouse-y", `${y * 100}%`);
    el.style.setProperty("--tilt-x", `${(0.5 - y) * 4}deg`);
    el.style.setProperty("--tilt-y", `${(x - 0.5) * 5}deg`);
  };
  const onPointerLeave = (e) => {
    e.currentTarget.style.setProperty("--tilt-x", "0deg");
    e.currentTarget.style.setProperty("--tilt-y", "0deg");
  };

  return (
    <div
      className="experience-card"
      onPointerMove={onPointerMove}
      onPointerLeave={onPointerLeave}
      style={{
        border: `1px solid ${getColor()}30`,
        backgroundColor: theme.name === "light" ? "#ffffff" : "#1d1d1d",
        "--exp-color": getColor(),
      }}
    >
      <div className="experience-card-logo-div">
        <img
          className="experience-card-logo"
          src={require(`../../assests/images/${experience["logo_path"]}`)}
          alt={experience.company}
        />
      </div>
      <div className="experience-card-body-div">
        <div className="experience-card-header-div">
          <div>
            <h3 className="experience-card-title" style={{ color: theme.text }}>
              {experience["title"]}
            </h3>
            <p
              className="experience-card-company"
              style={{ color: theme.secondaryText }}
            >
              <a
                href={experience["company_url"]}
                target="_blank"
                rel="noopener noreferrer"
                style={{ color: getColor() }}
              >
                {experience["company"]}
              </a>
            </p>
          </div>
          <div>
            <p
              className="experience-card-duration"
              style={{ color: theme.secondaryText }}
            >
              {formatDuration(experience["duration"])}
              {isCurrent && (
                <span className="exp-live-badge">
                  <span className="exp-live-badge-dot" aria-hidden="true" />
                  Now
                </span>
              )}
            </p>
            <p
              className="experience-card-location"
              style={{ color: theme.secondaryText }}
            >
              {formatLocation(experience["location"])}
            </p>
          </div>
        </div>
        <p
          className="experience-card-description"
          style={{ color: theme.text }}
        >
          {experience["description"]}
        </p>
        {experience["github_link"] && (
          <a
            href={experience["github_link"]}
            target="_blank"
            rel="noopener noreferrer"
            className="experience-card-github-link"
          >
            <button className="experience-card-github-button">
              {experience["button_text"] || "View Project"}
            </button>
          </a>
        )}
      </div>
    </div>
  );
}

export default ExperienceCard;
