import { experience, projects } from "../../../portfolio.js";

/* The work roles, oldest first, with their logo files resolved and the
   projects shipped in each, for the Experience hero visuals. */

const work = ((experience.sections || []).find((s) => s.title === "Work") || { experiences: [] }).experiences;

// Projects shipped in each role, keyed by the role's logo file.
const ROLE_PROJECTS = {
  "assist.png": ["ravi-visual-assistant", "table-recognition-system", "ravi-accessible-stem-education"],
  "cams.png": ["cams-lens", "ai-email-automation"],
  "Think_logo.png": ["camscode", "intelligent-document-processing"],
};

const logoUrl = (file) => {
  try {
    const m = require(`../../../assests/images/${file}`);
    return m.default || m;
  } catch (e) {
    return null;
  }
};

const projectBySlug = Object.fromEntries(((projects && projects.data) || []).map((p) => [p.slug, p]));

// Short display names for the "Shipped" line (the project titles in
// portfolio.js are long and some share a prefix, e.g. "RAVI - …").
const SHORT_NAMES = {
  "ravi-visual-assistant": "RAVI Visual Assistant",
  "table-recognition-system": "Table Recognition",
  "ravi-accessible-stem-education": "Accessible STEM",
  "cams-lens": "CAMS Lens",
  "ai-email-automation": "AI Email Automation",
  camscode: "CAMSCode",
  "intelligent-document-processing": "Document Processing",
};
const shippedFor = (logoFile) =>
  (ROLE_PROJECTS[logoFile] || [])
    .filter((slug) => projectBySlug[slug])
    .map((slug) => ({ slug, name: SHORT_NAMES[slug] || slug }));

// The three main roles (skip the short project entry), oldest first.
export const HERO_ROLES = work
  .filter((r) => !/project/i.test(r.title) && !/intern/i.test(r.title))
  .slice(0, 3)
  .reverse()
  .map((r) => ({
    title: r.title,
    company: r.company,
    duration: r.duration,
    color: r.color || "#2962FF",
    logo: logoUrl(r.logo_path),
    shipped: shippedFor(r.logo_path),
  }));

export const loadImage = (src) =>
  new Promise((resolve) => {
    if (!src) return resolve(null);
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => resolve(null);
    img.src = src;
  });
